pragma solidity ^0.8.0;
// Versione corretta del pattern "logica separata dallo stato" di CreatedSeparation.sol
contract Created {
    CreatedStorage private stateContract;
    address private immutable owner;

    modifier onlyOwner() { require(msg.sender == owner, "Only owner"); _; }

    constructor() { owner = msg.sender; }

    function firstSetUp(uint a) public onlyOwner {
        require(address(stateContract) == address(0), "Already set up");
        stateContract = new CreatedStorage(a);
    }
    function increment() public { stateContract.setX(stateContract.getX() + 1); }
    function get() public view returns (uint) { return stateContract.getX(); }
    function test() public { stateContract.setTestAddr(msg.sender); }

    // chiamata dal proprietario sulla VECCHIA logica
    function migrateTo(address newLogic) public onlyOwner {
        CreatedStorage s = stateContract;
        s.updateLogic(newLogic);                 // lo storage ora accetta scritture solo dalla nuova logica
        stateContract = CreatedStorage(address(0));
        Created(newLogic).adoptStorage(address(s)); // la nuova logica memorizza il link allo storage
    }
    // chiamata dalla vecchia logica sulla NUOVA: accetta solo uno storage che punta già a questo contratto
    function adoptStorage(address s) external {
        require(address(stateContract) == address(0), "Already has storage");
        require(CreatedStorage(s).logicAddr() == address(this), "Storage not linked to me");
        stateContract = CreatedStorage(s);
    }
}

contract CreatedStorage {
    address public testAddr;
    uint public x;
    address public logicAddr;

    modifier onlyLogic() { require(msg.sender == logicAddr, "Only logic"); _; }

    constructor(uint a) { x = a; logicAddr = msg.sender; }
    function updateLogic(address newLogic) external onlyLogic { logicAddr = newLogic; }
    function getX() public view returns (uint) { return x; }
    function setX(uint _x) public onlyLogic { x = _x; }
    function getTestAddr() public view returns (address) { return testAddr; }
    function setTestAddr(address addr) public onlyLogic { testAddr = addr; }
}

