# Modello in Python puro della reentrancy di Victim.sol / Attacker.sol
# Ogni chiamata esterna è atomica: se il chiamato fa "revert" (AssertionError), il suo effetto viene annullato.
class Victim:
    def __init__(self, safe=False):
        self.shares, self.balance, self.safe, self.log = {}, 0, safe, []

    def deposit(self, who, amount):
        self.shares[who] = self.shares.get(who, 0) + amount
        self.balance += amount

    def withdraw(self, who):
        amount = self.shares.get(who, 0)
        assert amount > 0, "Empty balance"                 # Checks
        if self.safe:
            self.shares[who] = 0                           # Effects PRIMA dell'interazione
        success = external_call(self, who, amount)         # Interactions
        if self.safe:
            assert success, "Transfer failed"              # require(success)
        elif success:
            self.shares[who] = 0                           # versione vulnerabile: effetto troppo tardi
        return success

class Attacker:
    def __init__(self):
        self.balance = 0
    def receive(self, victim, amount):
        if victim.balance > 1:                             # come Attacker.sol: soglia 1 ether
            victim.withdraw(self)

def external_call(victim, to, amount):
    """CALL con valore: fallisce senza revert se il saldo non basta; annulla tutto se il chiamato fa revert."""
    if amount > victim.balance:
        return False
    snap = (dict(victim.shares), victim.balance, list(victim.log), to.balance)
    victim.balance -= amount; to.balance += amount; victim.log.append(amount)
    try:
        to.receive(victim, amount)
        return True
    except AssertionError:
        victim.shares, victim.balance, victim.log, to.balance = snap
        return False

def run(safe, attacker_deposit=1):
    v, a = Victim(safe), Attacker()
    for name, amt in [("alice", 3), ("bob", 2), ("carol", 5)]:
        v.deposit(name, amt)
    v.deposit(a, attacker_deposit)
    try:
        ok = v.withdraw(a)
    except AssertionError as e:
        ok = f"revert ({e})"
        v.shares[a] = attacker_deposit                     # revert della tx intera: lo stato torna com'era
    print(f"safe={safe!s:5} deposito={attacker_deposit}: esito={ok}, prelievi={v.log}, "
          f"attaccante={a.balance} ETH, vittima={v.balance} ETH (deve agli onesti 10 ETH)")

run(False)
run(False, 4)
run(True)

# Aritmetica uint256: "unchecked" (Solidity < 0.8) contro "checked" (Solidity >= 0.8)
MOD = 2**256
MAX = MOD - 1

def add_unchecked(a, b):
    return (a + b) % MOD

def add_checked(a, b):
    r = a + b
    if r > MAX:
        raise OverflowError("Panic(0x11)")
    return r

t = 1_777_000_000 + 7 * 24 * 3600          # lockTime = block.timestamp + 1 weeks
x = add_unchecked(add_unchecked(MAX, 1), -t % MOD)  # type(uint).max + 1 - t, calcolato come in 0.7
print("x = 2^256 - t ?", x == MOD - t)
print("x ha", len(str(x)), "cifre decimali")
print("lockTime dopo increaseLockTime (0.7):", add_unchecked(t, x))
try:
    add_checked(t, x)
except OverflowError as e:
    print("lockTime con 0.8:", e)
try:
    add_checked(MAX, 1)
except OverflowError as e:
    print("già type(uint).max + 1 con 0.8:", e)

