// SPDX-License-Identifier: GPL-3.0
pragma solidity ^0.8.20;

// Proxy minimale: lo STATO vive qui, la LOGICA nel contratto "implementation".
// Gli indirizzi di admin e implementation stanno in slot pseudo-casuali (EIP-1967)
// per non collidere con le variabili della logica (che partono dallo slot 0).
contract MiniProxy {
    bytes32 private constant IMPL_SLOT  = bytes32(uint256(keccak256("eip1967.proxy.implementation")) - 1);
    bytes32 private constant ADMIN_SLOT = bytes32(uint256(keccak256("eip1967.proxy.admin")) - 1);

    constructor(address impl) {
        _set(IMPL_SLOT, impl);
        _set(ADMIN_SLOT, msg.sender);
    }

    function upgradeTo(address newImpl) external {
        require(msg.sender == _get(ADMIN_SLOT), "Only admin");
        _set(IMPL_SLOT, newImpl);
    }

    function implementation() external view returns (address) { return _get(IMPL_SLOT); }

    // ogni altra chiamata viene eseguita con il codice di impl ma sullo storage del proxy
    fallback() external payable {
        address impl = _get(IMPL_SLOT);
        assembly {
            calldatacopy(0, 0, calldatasize())
            let ok := delegatecall(gas(), impl, 0, calldatasize(), 0, 0)
            returndatacopy(0, 0, returndatasize())
            switch ok case 0 { revert(0, returndatasize()) } default { return(0, returndatasize()) }
        }
    }
    receive() external payable {}

    function _get(bytes32 s) private view returns (address a) { assembly { a := sload(s) } }
    function _set(bytes32 s, address a) private { assembly { sstore(s, a) } }
}

contract CounterV1 {
    uint public x;                       // slot 0 (nello storage del proxy!)
    function increment() public { x += 1; }
}

contract CounterV2 {
    uint public x;                       // stesso layout: la nuova versione può solo AGGIUNGERE variabili in coda
    uint public stopped;                 // slot 1, nuova variabile
    function increment() public { require(stopped == 0, "Stopped"); x += 1; }
    function stop() public { stopped = 1; } // "disaster recovery" (manca il controllo sul chiamante: vedi testo)
}
